"use strict";(self.webpackChunkwww=self.webpackChunkwww||[]).push([[26911],{96238:(e,t,h)=>{h.r(t),h.d(t,{assets:()=>d,contentTitle:()=>o,default:()=>u,frontMatter:()=>s,metadata:()=>i,toc:()=>r});var n=h(31085),a=h(71184);const s={sidebar_position:8,slug:"/bible/Luke/Luke_8",title:"Luke 8",hide_table_of_contents:!0},o="Luke",i={id:"bible/Luke/Luke 8",title:"Luke 8",description:"Chapter 8",source:"@site/docs/bible/Luke/Luke 8.md",sourceDirName:"bible/Luke",slug:"/bible/Luke/Luke_8",permalink:"/bibleNotes/docs/bible/Luke/Luke_8",draft:!1,unlisted:!1,editUrl:"https://github.com/ozkey/bibleNotes/tree/main/packages/www/docs/bible/Luke/Luke 8.md",tags:[],version:"current",sidebarPosition:8,frontMatter:{sidebar_position:8,slug:"/bible/Luke/Luke_8",title:"Luke 8",hide_table_of_contents:!0},sidebar:"bibleSidebar",previous:{title:"Luke 7",permalink:"/bibleNotes/docs/bible/Luke/Luke_7"},next:{title:"Luke 9",permalink:"/bibleNotes/docs/bible/Luke/Luke_9"}},d={},r=[{value:"Chapter 8",id:"chapter-8",level:2}];function l(e){const t={admonition:"admonition",h1:"h1",h2:"h2",p:"p",...(0,a.R)(),...e.components},{BibleText:h}=t;return h||function(e,t){throw new Error("Expected "+(t?"component":"object")+" `"+e+"` to be defined: you likely forgot to import, pass, or provide it.")}("BibleText",!0),(0,n.jsxs)(n.Fragment,{children:[(0,n.jsx)(t.h1,{id:"luke",children:"Luke"}),"\n",(0,n.jsx)(t.h2,{id:"chapter-8",children:"Chapter 8"}),"\n",(0,n.jsx)(t.p,{children:"The parable of the seed.  Christ stills the storm at sea, casts out the legion, heals the issue of blood and raises the daughter of Jairus to life."}),"\n",(0,n.jsx)(h,{verse:1,children:"And it came to pass afterwards he travelled through the cities and towns, preaching and evangelizing the kingdom of God: and the twelve with him:"}),"\n",(0,n.jsx)(h,{verse:2,children:"And certain women who had been healed of evil spirits and infirmities: Mary who is called Magdalen, out of whom seven devils were gone forth,"}),"\n",(0,n.jsx)(h,{verse:3,children:"And Joanna the wife of Chusa, Herod's steward, and Susanna and many others who ministered unto him of their substance."}),"\n",(0,n.jsx)(h,{verse:4,children:"And when a very great multitude was gathered together and hastened out of the cities, unto him, he spoke by a similitude."}),"\n",(0,n.jsx)(h,{verse:5,children:"The sower went out to sow his seed. And as he sowed, some fell by the way side. And it was trodden down: and the fowls of the air devoured it."}),"\n",(0,n.jsx)(h,{verse:6,children:"And other some fell upon a rock. And as soon as it was sprung up, it withered away, because it had no moisture."}),"\n",(0,n.jsx)(h,{verse:7,children:"And other some fell among thorns. And the thorns growing up with it, choked it."}),"\n",(0,n.jsx)(h,{verse:8,children:"And other some fell upon good ground and, being sprung up, yielded fruit a hundredfold. Saying these things, he cried out: He that hath ears to hear, let him hear."}),"\n",(0,n.jsx)(h,{verse:9,children:"And his disciples asked him what this parable might be."}),"\n",(0,n.jsx)(h,{verse:10,children:"To whom he said: To you it is given to know the mystery of the kingdom of God; but to the rest in parables, that seeing they may not see and hearing may not understand."}),"\n",(0,n.jsx)(t.admonition,{type:"note",children:(0,n.jsx)(t.p,{children:"Note 1: Seeing they may not see...See the annotation, Mark 4. 12."})}),"\n",(0,n.jsx)(h,{verse:11,children:"Now the parable is this: The seed is the word of God."}),"\n",(0,n.jsx)(h,{verse:12,children:"And they by the way side are they that hear: then the devil cometh and taketh the word out of their heart, lest believing they should be saved."}),"\n",(0,n.jsx)(h,{verse:13,children:"Now they upon the rock are they who when they hear receive the word with joy: and these have no roots: for they believe for a while and in time of temptation they fall away."}),"\n",(0,n.jsx)(h,{verse:14,children:"And that which fell among thorns are they who have heard and, going their way, are choked with the cares and riches and pleasures of this life and yield no fruit."}),"\n",(0,n.jsx)(h,{verse:15,children:"But that on the good ground are they who in a good and perfect heart, hearing the word, keep it and bring forth fruit in patience."}),"\n",(0,n.jsx)(h,{verse:16,children:"Now no man lighting a candle covereth it with a vessel or putteth it under a bed: but setteth it upon a candlestick, that they who come in may see the light."}),"\n",(0,n.jsx)(h,{verse:17,children:"For there is not any thing secret that shall not be made manifest, nor hidden that shall not be known and come abroad."}),"\n",(0,n.jsx)(h,{verse:18,children:"Take heed therefore how you hear. For whosoever hath, to him shall be given: and whosoever hath not, that also which he thinketh he hath shall be taken away from him."}),"\n",(0,n.jsx)(h,{verse:19,children:"And his mother and brethren came unto him: and they could not come at him for the crowd."}),"\n",(0,n.jsx)(h,{verse:20,children:"And it was told him: Thy mother and thy brethren stand without, desiring to see thee."}),"\n",(0,n.jsx)(h,{verse:21,children:"Who answering, said to them: My mother and my brethren are they who hear the word of God and do it."}),"\n",(0,n.jsx)(h,{verse:22,children:"And it came to pass on a certain day that he went into a little ship with his disciples. And he said to them: Let us go over to the other side of the lake. And they launched forth."}),"\n",(0,n.jsx)(h,{verse:23,children:"And when they were sailing, he slept. And there came down a storm of wind upon the lake: and they were filled and were in danger."}),"\n",(0,n.jsx)(h,{verse:24,children:"And they came and awaked him, saying: Master, we perish. But he arising, rebuked the wind and the rage of the water. And it ceased: and there was a calm."}),"\n",(0,n.jsx)(h,{verse:25,children:"And he said to them: Where is your faith? Who being afraid, wondered, saying one to another: Who is this (think you), that he commandeth both the winds and the sea: and they obey him?"}),"\n",(0,n.jsx)(h,{verse:26,children:"And they sailed to the country of the Gerasens, which is over against Galilee."}),"\n",(0,n.jsx)(h,{verse:27,children:"And when he was come forth to the land, there met him a certain man who had a devil now a very long time. And he wore no clothes: neither did he abide in a house, but in the sepulchres."}),"\n",(0,n.jsx)(h,{verse:28,children:"And when he saw Jesus, he fell down before him. And crying out with a loud voice, he said: What have I to do with thee, Jesus, Son of the most high God? I beseech thee, do not torment me."}),"\n",(0,n.jsx)(h,{verse:29,children:"For he commanded the unclean spirit to go out of the man. For many times it seized him: and he was bound with chains and kept in fetters: and breaking the bonds, he was driven by the devil into the deserts."}),"\n",(0,n.jsx)(h,{verse:30,children:"And Jesus asked him, saying: What is thy name? But he said: Legion. Because many devils were entered into him."}),"\n",(0,n.jsx)(h,{verse:31,children:"And they besought him that he would not command them to go into the abyss."}),"\n",(0,n.jsx)(h,{verse:32,children:"And there was there a herd of many swine feeding on the mountain: and they besought him that he would suffer them to enter into them. And he suffered them."}),"\n",(0,n.jsx)(h,{verse:33,children:"The devils therefore went out of the man and entered into the swine. And the herd ran violently down a steep place into the lake and were stifled."}),"\n",(0,n.jsx)(h,{verse:34,children:"Which when they that fed them saw done, they fled away and told it in the city and in the villages."}),"\n",(0,n.jsx)(h,{verse:35,children:"And they went out to see what was done. And they came to Jesus and found the man out of whom the devils were departed, sitting at his feet, clothed and in his right mind. And they were afraid."}),"\n",(0,n.jsx)(h,{verse:36,children:"And they also that had seen told them how he had been healed from the legion."}),"\n",(0,n.jsx)(h,{verse:37,children:"And all the multitude of the country of the Gerasens besought him to depart from them: for they were taken with great fear. And he, going up into the ship, returned back again."}),"\n",(0,n.jsx)(h,{verse:38,children:"Now the man out of whom the devils were departed besought him that he might be with him. But Jesus sent him away, saying:"}),"\n",(0,n.jsx)(h,{verse:39,children:"Return to thy house and tell how great things God hath done to thee. And he went through the whole city, publishing how great things Jesus had done to him."}),"\n",(0,n.jsx)(h,{verse:40,children:"And it came to pass that when Jesus was returned, the multitude received him: for they were all waiting for him."}),"\n",(0,n.jsx)(h,{verse:41,children:"And behold there came a man whose name was Jairus: and he was a ruler of the synagogue. And he fell down at the feet of Jesus, beseeching him that he would come into his house:"}),"\n",(0,n.jsx)(h,{verse:42,children:"For he had an only daughter, almost twelve years old, and she was dying. And it happened as he went that he was thronged by the multitudes."}),"\n",(0,n.jsx)(h,{verse:43,children:"And there was a certain woman having an issue of blood twelve years, who had bestowed all her substance on physicians and could not be healed by any."}),"\n",(0,n.jsx)(h,{verse:44,children:"She came behind him and touched the hem of his garment: and immediately the issue of her blood stopped."}),"\n",(0,n.jsx)(h,{verse:45,children:"And Jesus said: Who is it that touched me? And all denying, Peter and they that were with him said: Master, the multitudes throng and press thee; and dost thou say, who touched me?"}),"\n",(0,n.jsx)(h,{verse:46,children:"And Jesus said: Somebody hath touched me; for I know that virtue is gone out from me."}),"\n",(0,n.jsx)(h,{verse:47,children:"And the woman seeing that she was not hid, came trembling and fell down before his feet and declared before all the people for what cause she had touched him, and how she was immediately healed."}),"\n",(0,n.jsx)(h,{verse:48,children:"But he said to her: Daughter, thy faith hath made thee whole. Go thy way in peace."}),"\n",(0,n.jsx)(h,{verse:49,children:"As he was yet speaking, there cometh one to the ruler of the synagogue, saying to him: Thy daughter is dead: trouble him not."}),"\n",(0,n.jsx)(h,{verse:50,children:"And Jesus hearing this word, answered the father of the maid: Fear not. Believe only: and she shall be safe."}),"\n",(0,n.jsx)(h,{verse:51,children:"And when he was come to the house, he suffered not any man to go in with him, but Peter and James and John, and the father and mother of the maiden."}),"\n",(0,n.jsx)(h,{verse:52,children:"And all wept and mourned for her. But he said: Weep not. The maid is not dead, but sleepeth."}),"\n",(0,n.jsx)(h,{verse:53,children:"And they laughed him to scorn, knowing that she was dead."}),"\n",(0,n.jsx)(h,{verse:54,children:"But he taking her by the hand, cried out, saying: Maid, arise."}),"\n",(0,n.jsx)(h,{verse:55,children:"And her spirit returned: and she arose immediately. And he bid them give her to eat."}),"\n",(0,n.jsx)(h,{verse:56,children:"And her parents were astonished, whom he charged to tell no man what was done."})]})}function u(e={}){const{wrapper:t}={...(0,a.R)(),...e.components};return t?(0,n.jsx)(t,{...e,children:(0,n.jsx)(l,{...e})}):l(e)}},71184:(e,t,h)=>{h.d(t,{R:()=>o,x:()=>i});var n=h(14041);const a={},s=n.createContext(a);function o(e){const t=n.useContext(s);return n.useMemo((function(){return"function"==typeof e?e(t):{...t,...e}}),[t,e])}function i(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(a):e.components||a:o(e.components),n.createElement(s.Provider,{value:t},e.children)}}}]);